\u003c/p\u003e\n\u003cdiv class=\"highlight highlight-source-sql notranslate position-relative overflow-auto\" dir=\"auto\" data-snippet-clipboard-copy-content=\"CALL StudentAge(20);\"\u003e\u003cpre\u003eCALL StudentAge(\u003cspan class=\"pl-c1\"\u003e20\u003c/span\u003e);\u003c/pre\u003e\u003c/div\u003e\n\u003chr\u003e\n\u003cdiv class=\"markdown-heading\" dir=\"auto\"\u003e\u003ch1 tabindex=\"-1\" class=\"heading-element\" dir=\"auto\"\u003e28. Trigger\u003c/h1\u003e\u003ca id=\"user-content-28-trigger\" class=\"anchor\" aria-label=\"Permalink: 28. Trigger\" href=\"#28-trigger\"\u003e\u003csvg data-component=\"Octicon\" class=\"octicon octicon-link\" viewBox=\"0 0 16 16\" version=\"1.1\" width=\"16\" height=\"16\" aria-hidden=\"true\"\u003e\u003cpath d=\"m7.775 3.275 1.25-1.25a3.5 3.5 0 1 1 4.95 4.95l-2.5 2.5a3.5 3.5 0 0 1-4.95 0 .751.751 0 0 1 .018-1.042.751.751 0 0 1 1.042-.018 1.998 1.998 0 0 0 2.83 0l2.5-2.5a2.002 2.002 0 0 0-2.83-2.83l-1.25 1.25a.751.751 0 0 1-1.042-.018.751.751 0 0 1-.018-1.042Zm-4.69 9.64a1.998 1.998 0 0 0 2.83 0l1.25-1.25a.751.751 0 0 1 1.042.018.751.751 0 0 1 .018 1.042l-1.25 1.25a3.5 3.5 0 1 1-4.95-4.95l2.5-2.5a3.5 3.5 0 0 1 4.95 0 .751.751 0 0 1-.018 1.042.751.751 0 0 1-1.042.018 1.998 1.998 0 0 0-2.83 0l-2.5 2.5a1.998 1.998 0 0 0 0 2.83Z\"\u003e\u003c/path\u003e\u003c/svg\u003e\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"markdown-heading\" dir=\"auto\"\u003e\u003ch2 tabindex=\"-1\" class=\"heading-element\" dir=\"auto\"\u003eBEFORE INSERT Trigger\u003c/h2\u003e\u003ca id=\"user-content-before-insert-trigger\" class=\"anchor\" aria-label=\"Permalink: BEFORE INSERT Trigger\" href=\"#before-insert-trigger\"\u003e\u003csvg data-component=\"Octicon\" class=\"octicon octicon-link\" viewBox=\"0 0 16 16\" version=\"1.1\" width=\"16\" height=\"16\" aria-hidden=\"true\"\u003e\u003cpath d=\"m7.775 3.275 1.25-1.25a3.5 3.5 0 1 1 4.95 4.95l-2.5 2.5a3.5 3.5 0 0 1-4.95 0 .751.751 0 0 1 .018-1.042.751.751 0 0 1 1.042-.018 1.998 1.998 0 0 0 2.83 0l2.5-2.5a2.002 2.002 0 0 0-2.83-2.83l-1.25 1.25a.751.751 0 0 1-1.042-.018.751.751 0 0 1-.018-1.042Zm-4.69 9.64a1.998 1.998 0 0 0 2.83 0l1.25-1.25a.751.751 0 0 1 1.042.018.751.751 0 0 1 .018 1.042l-1.25 1.25a3.5 3.5 0 1 1-4.95-4.95l2.5-2.5a3.5 3.5 0 0 1 4.95 0 .751.751 0 0 1-.018 1.042.751.751 0 0 1-1.042.018 1.998 1.998 0 0 0-2.83 0l-2.5 2.5a1.998 1.998 0 0 0 0 2.83Z\"\u003e\u003c/path\u003e\u003c/svg\u003e\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"highlight highlight-source-sql notranslate position-relative overflow-auto\" dir=\"auto\" data-snippet-clipboard-copy-content=\"DELIMITER //\n\nCREATE TRIGGER before_insert_student\nBEFORE INSERT\nON student\nFOR EACH ROW\nBEGIN\nSET NEW.name=UPPER(NEW.name);\nEND //\n\nDELIMITER ;\"\u003e\u003cpre\u003eDELIMITER \u003cspan class=\"pl-k\"\u003e//\u003c/span\u003e\n\n\u003cspan class=\"pl-k\"\u003eCREATE\u003c/span\u003e \u003cspan class=\"pl-k\"\u003eTRIGGER\u003c/span\u003e \u003cspan class=\"pl-en\"\u003ebefore_insert_student\u003c/span\u003e\nBEFORE INSERT\n\u003cspan class=\"pl-k\"\u003eON\u003c/span\u003e student\nFOR EACH ROW\n\u003cspan class=\"pl-k\"\u003eBEGIN\u003c/span\u003e\n\u003cspan class=\"pl-k\"\u003eSET\u003c/span\u003e \u003cspan class=\"pl-c1\"\u003eNEW\u003c/span\u003e.\u003cspan class=\"pl-c1\"\u003ename\u003c/span\u003e\u003cspan class=\"pl-k\"\u003e=\u003c/span\u003e\u003cspan class=\"pl-c1\"\u003eUPPER\u003c/span\u003e(\u003cspan class=\"pl-c1\"\u003eNEW\u003c/span\u003e.\u003cspan class=\"pl-c1\"\u003ename\u003c/span\u003e);\nEND \u003cspan class=\"pl-k\"\u003e//\u003c/span\u003e\n\nDELIMITER ;\u003c/pre\u003e\u003c/div\u003e\n\u003cp dir=\"auto\"\u003eInsert\u003c/p\u003e\n\u003cdiv class=\"highlight highlight-source-sql notranslate position-relative overflow-auto\" dir=\"auto\" data-snippet-clipboard-copy-content=\"INSERT INTO student\nVALUES(2,'rahul',21,'r@mail.com');\"\u003e\u003cpre\u003e\u003cspan class=\"pl-k\"\u003eINSERT INTO\u003c/span\u003e student\n\u003cspan class=\"pl-k\"\u003eVALUES\u003c/span\u003e(\u003cspan class=\"pl-c1\"\u003e2\u003c/span\u003e,\u003cspan class=\"pl-s\"\u003e\u003cspan class=\"pl-pds\"\u003e'\u003c/span\u003erahul\u003cspan class=\"pl-pds\"\u003e'\u003c/span\u003e\u003c/span\u003e,\u003cspan class=\"pl-c1\"\u003e21\u003c/span\u003e,\u003cspan class=\"pl-s\"\u003e\u003cspan class=\"pl-pds\"\u003e'\u003c/span\u003er@mail.com\u003cspan class=\"pl-pds\"\u003e'\u003c/span\u003e\u003c/span\u003e);\u003c/pre\u003e\u003c/div\u003e\n\u003cp dir=\"auto\"\u003eOutput\u003c/p\u003e\n\u003cmarkdown-accessiblity-table\u003e\u003ctable\u003e\n\u003cthead\u003e\n\u003ctr\u003e\n\u003cth\u003eid\u003c/th\u003e\n\u003cth\u003ename\u003c/th\u003e\n\u003c/tr\u003e\n\u003c/thead\u003e\n\u003ctbody\u003e\n\u003ctr\u003e\n\u003ctd\u003e2\u003c/td\u003e\n\u003ctd\u003eRAHUL\u003c/td\u003e\n\u003c/tr\u003e\n\u003c/tbody\u003e\n\u003c/table\u003e\u003c/markdown-accessiblity-table\u003e\n\u003chr\u003e\n\u003cdiv class=\"markdown-heading\" dir=\"auto\"\u003e\u003ch2 tabindex=\"-1\" class=\"heading-element\" dir=\"auto\"\u003eAFTER INSERT Trigger\u003c/h2\u003e\u003ca id=\"user-content-after-insert-trigger\" class=\"anchor\" aria-label=\"Permalink: AFTER INSERT Trigger\" href=\"#after-insert-trigger\"\u003e\u003csvg data-component=\"Octicon\" class=\"octicon octicon-link\" viewBox=\"0 0 16 16\" version=\"1.1\" width=\"16\" height=\"16\" aria-hidden=\"true\"\u003e\u003cpath d=\"m7.775 3.275 1.25-1.25a3.5 3.5 0 1 1 4.95 4.95l-2.5 2.5a3.5 3.5 0 0 1-4.95 0 .751.751 0 0 1 .018-1.042.751.751 0 0 1 1.042-.018 1.998 1.998 0 0 0 2.83 0l2.5-2.5a2.002 2.002 0 0 0-2.83-2.83l-1.25 1.25a.751.751 0 0 1-1.042-.018.751.751 0 0 1-.018-1.042Zm-4.69 9.64a1.998 1.998 0 0 0 2.83 0l1.25-1.25a.751.751 0 0 1 1.042.018.751.751 0 0 1 .018 1.042l-1.25 1.25a3.5 3.5 0 1 1-4.95-4.95l2.5-2.5a3.5 3.5 0 0 1 4.95 0 .751.751 0 0 1-.018 1.042.751.751 0 0 1-1.042.018 1.998 1.998 0 0 0-2.83 0l-2.5 2.5a1.998 1.998 0 0 0 0 2.83Z\"\u003e\u003c/path\u003e\u003c/svg\u003e\u003c/a\u003e\u003c/div\u003e\n\u003cdiv class=\"highlight highlight-source-sql notranslate position-relative overflow-auto\" dir=\"auto\" data-snippet-clipboard-copy-content=\"CREATE TABLE student_log(\nmessage VARCHAR(100)\n);\"\u003e\u003cpre\u003e\u003cspan class=\"pl-k\"\u003eCREATE\u003c/span\u003e \u003cspan class=\"pl-k\"\u003eTABLE\u003c/span\u003e \u003cspan class=\"pl-en\"\u003estudent_log\u003c/span\u003e(\nmessage \u003cspan class=\"pl-k\"\u003eVARCHAR\u003c/span\u003e(\u003cspan class=\"pl-c1\"\u003e100\u003c/span\u003e)\n);\u003c/pre\u003e\u003c/div\u003e\n\u003cdiv class=\"highlight highlight-source-sql notranslate position-relative overflow-auto\" dir=\"auto\" data-snippet-clipboard-copy-content=\"DELIMITER //\n\nCREATE TRIGGER after_insert_student\nAFTER INSERT\nON student\nFOR EACH ROW\nBEGIN\nINSERT INTO student_log\nVALUES('Student Inserted');\nEND //\n\nDELIMITER ;\"\u003e\u003cpre\u003eDELIMITER \u003cspan class=\"pl-k\"\u003e//\u003c/span\u003e\n\n\u003cspan class=\"pl-k\"\u003eCREATE\u003c/span\u003e \u003cspan class=\"pl-k\"\u003eTRIGGER\u003c/span\u003e \u003cspan class=\"pl-en\"\u003eafter_insert_student\u003c/span\u003e\nAFTER INSERT\n\u003cspan class=\"pl-k\"\u003eON\u003c/span\u003e student\nFOR EACH ROW\n\u003cspan class=\"pl-k\"\u003eBEGIN\u003c/span\u003e\n\u003cspan class=\"pl-k\"\u003eINSERT INTO\u003c/span\u003e student_log\n\u003cspan class=\"pl-k\"\u003eVALUES\u003c/span\u003e(\u003cspan class=\"pl-s\"\u003e\u003cspan class=\"pl-pds\"\u003e'\u003c/span\u003eStudent Inserted\u003cspan class=\"pl-pds\"\u003e'\u003c/span\u003e\u003c/span\u003e);\nEND \u003cspan class=\"pl-k\"\u003e//\u003c/span\u003e\n\nDELIMITER ;\u003c/pre\u003e\u003c/div\u003e\n\u003cp dir=\"auto\"\u003eOutput\u003c/p\u003e\n\u003cmarkdown-accessiblity-table\u003e\u003ctable\u003e\n\u003cthead\u003e\n\u003ctr\u003e\n\u003cth\u003emessage\u003c/th\u003e\n\u003c/tr\u003e\n\u003c/thead\u003e\n\u003ctbody\u003e\n\u003ctr\u003e\n\u003ctd\u003eStudent Inserted\u003c/td\u003e\n\