<markdown-accessiblity-table data-catalyst=""><table>
<thead>
<tr>
<th>Constraint</th>
<th>Purpose</th>
<th>Example</th>
</tr>
</thead>
<tbody>
<tr>
<td>PRIMARY KEY</td>
<td>Unique identifier</td>
<td><code>id INT PRIMARY KEY</code></td>
</tr>
<tr>
<td>FOREIGN KEY</td>
<td>Connects tables</td>
<td><code>FOREIGN KEY(dept_id) REFERENCES department(id)</code></td>
</tr>
<tr>
<td>NOT NULL</td>
<td>Cannot be empty</td>
<td><code>name VARCHAR(50) NOT NULL</code></td>
</tr>
<tr>
<td>UNIQUE</td>
<td>No duplicate values</td>
<td><code>email VARCHAR(100) UNIQUE</code></td>
</tr>
<tr>
<td>DEFAULT</td>
<td>Default value</td>
<td><code>age INT DEFAULT 18</code></td>
</tr>
<tr>
<td>AUTO_INCREMENT</td>
<td>Auto-generated number</td>
<td><code>id INT AUTO_INCREMENT</code></td>
</tr>
<tr>
<td>CHECK</td>
<td>Validates values</td>
<td><code>CHECK(age&gt;=18)</code></td>
</tr>
</tbody>
</table></markdown-accessiblity-table>
