<div class="highlight highlight-source-sql notranslate position-relative overflow-auto" dir="auto"><pre><span class="pl-k">CREATE</span> <span class="pl-k">TABLE</span> <span class="pl-en">department</span>(
id <span class="pl-k">INT</span> <span class="pl-k">PRIMARY KEY</span>,
dept_name <span class="pl-k">VARCHAR</span>(<span class="pl-c1">50</span>)
);

<span class="pl-k">CREATE</span> <span class="pl-k">TABLE</span> <span class="pl-en">student</span>(
id <span class="pl-k">INT</span> <span class="pl-k">PRIMARY KEY</span>,
name <span class="pl-k">VARCHAR</span>(<span class="pl-c1">50</span>),
dept_id <span class="pl-k">INT</span>,
<span class="pl-k">FOREIGN KEY</span>(dept_id)
<span class="pl-k">REFERENCES</span> department(id)
<span class="pl-k">ON DELETE CASCADE</span>
<span class="pl-k">ON</span> <span class="pl-k">UPDATE</span> CASCADE
);</pre><div class="zeroclipboard-container">
    <clipboard-copy aria-label="Copy code to clipboard" class="ClipboardButton btn btn-invisible js-clipboard-copy m-2 p-0 d-flex flex-justify-center flex-items-center" data-copy-feedback="Copied!" data-tooltip-direction="w" value="CREATE TABLE department(
id INT PRIMARY KEY,
dept_name VARCHAR(50)
);

