<div class="highlight highlight-source-sql notranslate position-relative overflow-auto" dir="auto"><pre>DELIMITER <span class="pl-k">//</span>

<span class="pl-k">CREATE</span> <span class="pl-k">TRIGGER</span> <span class="pl-en">before_insert_student</span>
BEFORE INSERT
<span class="pl-k">ON</span> student
FOR EACH ROW
<span class="pl-k">BEGIN</span>
<span class="pl-k">SET</span> <span class="pl-c1">NEW</span>.<span class="pl-c1">name</span><span class="pl-k">=</span><span class="pl-c1">UPPER</span>(<span class="pl-c1">NEW</span>.<span class="pl-c1">name</span>);
